(x, y, t) => {
  const cx = 240, cy = 120;
  const g1x = 240+Math.sin(t*0.2)*180, g1y = 120+Math.cos(t*0.15)*100;
  const g2x = 240+Math.cos(t*0.25+2)*160, g2y = 120+Math.sin(t*0.3+1)*80;
  const g3x = 240+Math.sin(t*0.18+4)*120, g3y = 120+Math.cos(t*0.22+3)*70;
  let wx = 0, wy = 0;
  for (const [gx, gy, mass] of [[g1x,g1y,1.0],[g2x,g2y,0.8],[g3x,g3y,0.6]]) {
    const dx = gx-x, dy = gy-y, d2 = dx*dx+dy*dy+1000, pull = mass*2000/d2;
    wx += dx*pull; wy += dy*pull;
  }
  const flow = Math.sin(x*0.015+t*0.3)*12+Math.cos(y*0.012-t*0.2)*10+Math.sin((x+y)*0.008+t*0.5)*8;
  const sx = x+wx*0.15+flow, sy = y+wy*0.15+flow;
  const src = [
    [g1x,g1y,0.09,2.2],[g2x,g2y,0.11,1.8],[g3x,g3y,0.07,2.5],
    [160+Math.cos(t*0.6+1)*100,60+Math.sin(t*0.5)*60,0.13,1.6],
    [320+Math.sin(t*0.45+3)*80,180+Math.cos(t*0.65)*50,0.08,2.1],
    [80+Math.cos(t*0.55+5)*70,200+Math.sin(t*0.4+2)*40,0.14,1.4],
    [400+Math.sin(t*0.35)*60,40+Math.cos(t*0.5+4)*50,0.1,2.3]
  ];
  let aS=0,iS=0,energy=0;
  for (const [sX,sY,f,sp] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp),inh=Math.sin(d*f*0.6+t*sp*0.5+1.2);
    aS+=a; iS+=inh; energy+=Math.abs(a)+Math.abs(inh);
  }
  const eNorm=energy/(src.length*2), act=aS/src.length, inh=iS/src.length;
  const n1=Math.sin(sx*0.035+sy*0.02+t*0.7),n2=Math.sin(sx*0.025-sy*0.035+t*1.0);
  const bg=(n1+n2)/2+Math.sin((sx+sy)*0.1+t*2.2)*0.3+Math.sin((sx-sy)*0.08-t*1.8)*0.3+Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.05-t*1.2)*0.4;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*4-t*1.8)+Math.sin(dist*0.035+ang*5-t*1.3))*0.35+Math.sin(dist*0.03-ang*2-t)*0.3;
  const raw=act-inh*0.65+bg*0.25+spiral;
  const reaction=Math.tanh(raw*3.2);
  const sharp=Math.sign(reaction)*Math.pow(Math.abs(reaction),0.65);
  const cell=Math.tanh((Math.sin(sx*0.12)*Math.sin(sy*0.12)+Math.sin((sx+sy)*0.08+t*0.8)*0.5)*2.0)*0.2;
  const kinetic=Math.abs(sharp),potential=1.0-kinetic;
  const eGlow=(kinetic*0.7+potential*0.3)*eNorm;
  const blend=sharp*0.8+cell*0.2, v=blend*0.5+0.5;
  const pal=[[2,2,8],[5,10,45],[10,40,120],[0,160,255],[0,255,220],[180,255,200],[255,255,255],[255,100,200],[255,0,150],[180,0,100],[60,0,60],[2,2,8]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.7+eGlow*0.5+Math.pow(Math.abs(sharp),0.5)*0.3;
  const edge=Math.abs(sharp)>0.6?1.35:(Math.abs(sharp)>0.3?1.1:0.85);
  const es=kinetic*0.1;
  return [
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+es*50))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge-es*30))|0
  ];
}
